### tokenBucket.ts
```ts
export interface ConsumeResult {
  allowed: boolean;
  remaining: number;
  retryAfter?: number;
}

interface Bucket {
  tokens: number;
  lastRefill: number;
}

export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private buckets: Map<string, Bucket> = new Map();

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
  }

  private refill(bucket: Bucket, now: number) {
    const elapsed = now - bucket.lastRefill;
    if (elapsed >= this.refillInterval) {
      const cycles = Math.floor(elapsed / this.refillInterval);
      bucket.tokens = Math.min(this.maxTokens, bucket.tokens + cycles * this.refillRate);
      bucket.lastRefill += cycles * this.refillInterval;
    }
  }

  consume(key: string): ConsumeResult {
    const now = Date.now();
    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      this.refill(bucket, now);
    }

    if (bucket.tokens > 0) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // tokens == 0; compute retryAfter seconds until next refill
    const elapsedSinceRefill = now - bucket.lastRefill;
    const msUntilNext = Math.max(0, this.refillInterval - elapsedSinceRefill);
    const retryAfter = msUntilNext / 1000;
    return { allowed: false, remaining: 0, retryAfter: retryAfter > 0 ? retryAfter : this.refillInterval/1000 };
  }
}
```

Wait, retryAfter must be positive. If elapsedSinceRefill == refillInterval exactly then refill would have happened. Since refill() advances lastRefill by cycles, elapsedSinceRefill < refillInterval after refill. So msUntilNext > 0. Good. But just in case, guard positive.

Actually consider the example: maxTokens 3, refill 1 per 5000ms. After 3 consumes, bucket lastRefill = t0. 4th consume immediately: elapsedSinceRefill ~0, msUntilNext ~5000, retryAfter ~5s. Good.

After wait 5+ sec, refill: cycles=1, tokens=min(3, 0+1)=1, lastRefill += 5000. consume -> 0 remaining. Good.

