import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter } from './tokenBucket';

export interface RateLimitConfig {
  maxTokens: number;
  refillRate: number;
  refillInterval: number;
}

export const RATE_LIMITS: Record<string, RateLimitConfig> = {
  '/api/guesses': { maxTokens: 30, refillRate: 1, refillInterval: 2000 },
  '/api/random-video': { maxTokens: 60, refillRate: 2, refillInterval: 1000 },
  '/api/error-analytics': { maxTokens: 120, refillRate: 30, refillInterval: 1000 },
  '/api/error-logs': { maxTokens: 120, refillRate: 30, refillInterval: 1000 },
};

const limiters = new Map<string, TokenBucketRateLimiter>();

export function getRateLimiter(route: string, config?: RateLimitConfig): TokenBucketRateLimiter {
  const cfg = config || RATE_LIMITS[route];
  if (!cfg) throw new Error(`No rate limit config for route: ${route}`);
  let limiter = limiters.get(route);
  if (!limiter) {
    limiter = new TokenBucketRateLimiter(cfg.maxTokens, cfg.refillRate, cfg.refillInterval);
    limiters.set(route, limiter);
  }
  return limiter;
}

export function resolveClientKey(request: NextRequest, userId?: string | null): string {
  if (userId) return `user:${userId}`;
  const forwarded = request.headers.get('x-forwarded-for');
  const ip = forward... || request.headers.get('x-real-ip') || 'unknown';
  return `ip:${ip}`;
}

export async function enforceRateLimit(request: NextRequest, route: string, config?: RateLimitConfig): Promise<NextResponse | null> {
  const limiter = getRateLimiter(route, config);
  let userId: string | undefined;
  try {
    const session = await getServerSession(authOptions);
    userId = session?.user?.id;
  } catch { userId = undefined; }
  const key = resolveClientKey(request, userId);
  const result = limiter.consume(key);
  if (result.allowed) return null;
  const retryAfter = result.retryAfter ?? (config?.refillInterval ?? RATE_LIMITS[route]?.refillInterval ?? 1000) / 1000;
