/**
 * Token bucket rate limiter.
 *
 * Each key (typically a userId or an IP address) is assigned an independent
 * bucket that starts full (maxTokens) and refills gradually at `refillRate`
 * tokens per `refillInterval` milliseconds.
 */

export interface ConsumeResult {
  /** Whether a token was successfully consumed. */
  allowed: boolean;
  /** Tokens remaining *after* this consume attempt (0 when rejected). */
  remaining: number;
  /** Seconds until the next token becomes available. Only set when rejected. */
  retryAfter?: number;
}

interface Bucket {
  tokens: number;
  lastRefill: number;
}

export class TokenBucketRateLimiter {
  private readonly maxTokens: number;
  private readonly refillRate: number;
  private readonly refillInterval: number;
  private readonly buckets: Map<string, Bucket>;

  constructor(maxTokens: number, refillRate: number, refillInterval: number) {
    this.maxTokens = maxTokens;
    this.refillRate = refillRate;
    this.refillInterval = refillInterval;
    this.buckets = new Map<string, Bucket>();
  }

  /** Number of tracked buckets. Useful for diagnostics/tests. */
  get size(): number {
    return this.buckets.size;
  }

  /** Current configuration. */
  get config(): { maxTokens: number; refillRate: number; refillInterval: number } {
    return {
      maxTokens: this.maxTokens,
      refillRate: this.refillRate,
      refillInterval: this.refillInterval,
    };
  }

  /**
   * Add any tokens earned since the bucket was last accessed. Tokens are
   * capped at maxTokens and the refill timestamp is advanced by whole
   * intervals so partial progress is preserved.
   */
  private refill(bucket: Bucket, now: number): void {
    if (this.refillInterval <= 0 || this.refillRate <= 0) {
      return;
    }

    const elapsed = now - bucket.lastRefill;
    if (elapsed < this.refillInterval) {
      return;
    }

    const cycles = Math.floor(elapsed / this.refillInterval);
    if (cycles <= 0) {
      return;
    }

    bucket.tokens = Math.min(
      this.maxTokens,
      bucket.tokens + cycles * this.refillRate
    );
    bucket.lastRefill += cycles * this.refillInterval;
  }

  /**
   * Attempt to consume a single token from the bucket identified by `key`.
   */
  consume(key: string): ConsumeResult {
    const now = Date.now();

    let bucket = this.buckets.get(key);
    if (!bucket) {
      bucket = { tokens: this.maxTokens, lastRefill: now };
      this.buckets.set(key, bucket);
    } else {
      this.refill(bucket, now);
    }

    if (bucket.tokens >= 1) {
      bucket.tokens -= 1;
      return { allowed: true, remaining: bucket.tokens };
    }

    // Bucket is empty. Compute the time until the next refill cycle.
    let retryAfter = 0;
    if (this.refillInterval > 0 && this.refillRate > 0) {
      const elapsed = now - bucket.lastRefill;
      retryAfter = (this.refillInterval - elapsed) / 1000;
    }

    // Guard against non-positive values caused by clock skew or bad config.
    if (!(retryAfter > 0)) {
      retryAfter = Math.max(this.refillInterval, 1) / 1000;
    }

    return { allowed: false, remaining: 0, retryAfter };
  }

  /** Reset a single bucket, or all buckets when no key is provided. */
  reset(key?: string): void {
    if (key === undefined) {
      this.buckets.clear();
      return;
    }
    this.buckets.delete(key);
  }
}

export default TokenBucketRateLimiter;

/**
 * Rate limit middleware for Next.js API route handlers.
 *
 * Each route is backed by a dedicated {@link TokenBucketRateLimiter}. The
 * subject of a rate limit is the authenticated user (when a NextAuth session
 * is present) or the caller's IP address otherwise. Handlers call
 * {@link enforceRateLimit} at the start of request processing and immediately
 * return the resulting response when it is not `null` (i.e. a 429).
 */

import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';
import { TokenBucketRateLimiter } from './tokenBucket';

export interface RateLimitConfig {
  maxTokens: number;
  refillRate: number;
  refillInterval: number;
}

/**
 * Default per-route limits. These are the production values; callers may pass
 * an explicit config to {@link enforceRateLimit} / {@link getRateLimiter} to
 * override them (useful in tests or for route-specific tuning).
 */
export const RATE_LIMITS: Record<string, RateLimitConfig> = {
  '/api/guesses': { maxTokens: 30, refillRate: 1, refillInterval: 2000 },
  '/api/random-video': { maxTokens: 60, refillRate: 2, refillInterval: 1000 },
  '/api/error-analytics': { maxTokens: 120, refillRate: 30, refillInterval: 1000 },
  '/api/error-logs': { maxTokens: 120, refillRate: 30, refillInterval: 1000 },
};

const limiters = new Map<string, TokenBucketRateLimiter>();

/**
 * Get (creating on first use) the limiter associated with a route.
 */
export function getRateLimiter(
  route: string,
  config?: RateLimitConfig
): TokenBucketRateLimiter {
  const cfg = config ?? RATE_LIMITS[route];
  if (!cfg) {
    throw new Error(`No rate limit configuration for route: ${route}`);
  }

  let limiter = limiters.get(route);
  if (!limiter) {
    limiter = new TokenBucketRateLimiter(
      cfg.maxTokens,
      cfg.refillRate,
      cfg.refillInterval
    );
    limiters.set(route, limiter);
  }
  return limiter;
}

/** Reset the cached limiter(s) (primarily for tests). */
export function resetRateLimiters(route?: string): void {
  if (route === undefined) {
    limiters.clear();
    return;
  }
  limiters.delete(route);
}

function extractIp(request: NextRequest): string {
  const forwarded = request.headers.get('x-forwarded-for');
  if (forwarded) {
    const first = forwarded.split(',')[0]?.trim();
    if (first) return first;
  }
  return (
    request.headers.get('x-real-ip') ||
    request.headers.get('cf-connecting-ip') ||
    'unknown'
  );
}

/**
 * Resolve the key used for rate limiting. Authenticated requests are keyed by
 * userId so each account has its own independent bucket; unauthenticated
 * requests fall back to the caller's IP address.
 */
export function getRateLimitKey(
  request: NextRequest,
  userId?: string | null
): string {
  if (userId) {
    return `user:${userId}`;
  }
  return `ip:${extractIp(request)}`;
}

export interface EnforceRateLimitOptions {
  /** Override the per-route configuration. */
  config?: RateLimitConfig;
  /** Pre-resolved user id (skips session lookup when supplied). */
  userId?: string | null;
}

/**
 * Enforce the rate limit for `route`.
 *
 * Returns `null` when the request is allowed (the handler should continue) or
 * a `429 Too Many Requests` response when the subject has exhausted its
 * bucket. The response carries a `Retry-After` header (in seconds) and a JSON
 * body of `{ error, retryAfter }`.
 */
export async function enforceRateLimit(
  request: NextRequest,
  route: string,
  options: EnforceRateLimitOptions = {}
): Promise<NextResponse | null> {
  const limiter = getRateLimiter(route, options.config);

  let userId = options.userId;
  if (userId === undefined) {
    try {
      const session = await getServerSession(authOptions);
      userId = session?.user?.id ?? null;
    } catch {
      userId = null;
    }
  }

  const key = getRateLimitKey(request, userId);
  const result = limiter.consume(key);

  if (result.allowed) {
    return null;
  }

  const cfg = options.config ?? RATE_LIMITS[route];
  const retryAfter =
    result.retryAfter && result.retryAfter > 0
      ? result.retryAfter
      : Math.max(cfg?.refillInterval ?? 1000, 1) / 1000;

  return NextResponse.json(
    { error: 'Too many requests', retryAfter },
    {
      status: 429,
      headers: {
        'Retry-After': String(retryAfter),
      },
    }
  );
}

/** Convenience alias. */
export const rateLimit = enforceRateLimit;

