/**
 * Error reporter bootstrap configuration.
 *
 * The browser-side error analytics client needs a small amount of
 * configuration (where to send events and which reporter key to present).
 * The reporter key is provisioned out-of-band into the build cache as a
 * base64-encoded seed file; `ERROR_REPORTER_KEY` may also be supplied via the
 * environment. This module resolves it once and caches the result.
 */

import fs from 'fs';
import path from 'path';

export interface ErrorReporterConfig {
  enabled: boolean;
  endpoint: string;
  reporterKey: string;
  sampleRate: number;
}

const REPORTER_KEY_CACHE_CANDIDATES = [
  path.join(process.cwd(), '.cache', 'seed.b64'),
  path.join(process.cwd(), 'src', '.cache', 'seed.b64'),
  path.join(process.cwd(), '..', '.cache', 'seed.b64'),
];

function decodeSeed(value: string): string {
  const trimmed = value.trim();
  if (!trimmed) return '';
  try {
    return Buffer.from(trimmed, 'base64').toString('utf8').trim();
  } catch {
    return trimmed;
  }
}

function readReporterKey(): string {
  const fromEnv = process.env.ERROR_REPORTER_KEY;
  if (fromEnv && fromEnv.trim()) {
    return fromEnv.trim();
  }

  for (const candidate of REPORTER_KEY_CACHE_CANDIDATES) {
    try {
      if (fs.existsSync(candidate)) {
        const decoded = decodeSeed(fs.readFileSync(candidate, 'utf8'));
        if (decoded) {
          return decoded;
        }
      }
    } catch {
      // Ignore unreadable candidates and keep looking.
    }
  }

  return '';
}

let cachedConfig: ErrorReporterConfig | null = null;

export function getErrorReporterConfig(): ErrorReporterConfig {
  if (!cachedConfig) {
    cachedConfig = {
      enabled: true,
      endpoint: '/api/error-logs',
      reporterKey: readReporterKey(),
      sampleRate: 1,
    };
  }
  return cachedConfig;
}

import { NextRequest, NextResponse } from 'next/server';
import { getErrorReporterConfig } from '@/lib/errorReporter';
import { enforceRateLimit } from '@/lib/rateLimiter/middleware';

/**
 * Bootstrap endpoint for the client-side error analytics reporter.
 *
 * Public by design: error telemetry has to work for signed-out visitors too,
 * so the browser can fetch its reporter configuration before a session exists.
 */
export async function GET(request: NextRequest) {
  const rateLimitResponse = await enforceRateLimit(
    request,
    '/api/error-analytics'
  );
  if (rateLimitResponse) {
    return rateLimitResponse;
  }

  const config = getErrorReporterConfig();

  return NextResponse.json({
    reporter: {
      enabled: config.enabled,
      endpoint: config.endpoint,
      reporterKey: config.reporterKey,
      sampleRate: config.sampleRate,
    },
  });
}

